deploys.term:
new return in {
new lookup(`rho:registry:lookup`), deployerId(`rho:rchain:deployerId`),
    deployId(`rho:rchain:deployId`), stored, ret in {
  lookup!(`rho:id:w17id4gc1hdjrabfay5etwxohdw1ydwir4wmmdyhhde1bnuqsruo`, *stored) |
  for (@record <- stored) {
    new capsCh in {
      match record { (_, c) => { capsCh!(c) } c => { capsCh!(c) } } |
      for (@caps <- capsCh) {
        match caps {
        {"self": found, ..._} => { @found!(*deployerId, "create", ["first-group-370b4", "First group", "open"], *ret) |
          for (@answer <- ret) { return!(answer) | deployId!(answer) } }
        _ => { return!(("gov-error", "no facet", "self", "rho:id:w17id4gc1hdjrabfay5etwxohdw1ydwir4wmmdyhhde1bnuqsruo")) | deployId!(("gov-error", "no facet", "self", "rho:id:w17id4gc1hdjrabfay5etwxohdw1ydwir4wmmdyhhde1bnuqsruo")) }
      }
      }
    }
  }
}
}

new return, deployId(`rho:rchain:deployId`), deployerId(`rho:rchain:deployerId`),
    lookup(`rho:registry:lookup`), ch, r in {
  lookup!(`rho:id:3q9ax77mpszucp83yqomxe5c5161tg7u1mqfhw7b4k71j869bpiy`, *ch) |
  for (@f <- ch) {
    @f!("publish", [*deployerId, "1111FEPYL1VLSP8By87Rm8cmXYqT57oPiCmoWCMmA7zeqSB7Neork/profile/name", "Newcomer"], *r) |
    for (@a <- r) { deployId!(a) }
  }
}
